operations.reducer:
const i = action.input;
if (i.name !== undefined) state.name = i.name;
if (i.kind !== undefined && i.kind !== null) state.kind = i.kind;
if (i.email !== undefined) state.email = i.email;
if (i.phone !== undefined) state.phone = i.phone;
if (i.website !== undefined) state.website = i.website;
if (i.vatId !== undefined) state.vatId = i.vatId;
if (i.registrationNumber !== undefined) state.registrationNumber = i.registrationNumber;
if (i.notes !== undefined) state.notes = i.notes;

operations.schema:
input SetAddressInput {
  street: String
  postalCode: String
  city: String
  country: String
}

operations.reducer:
state.address = {
  street: action.input.street ?? null,
  postalCode: action.input.postalCode ?? null,
  city: action.input.city ?? null,
  country: action.input.country ?? null,
};

operations.schema:
input SetBankDetailsInput {
  iban: String
  bic: String
  accountHolder: String
}

operations.reducer:
state.bank = {
  iban: action.input.iban ?? null,
  bic: action.input.bic ?? null,
  accountHolder: action.input.accountHolder ?? null,
};

operations.schema:
input SetPaymentTermsInput {
  paymentTermsDays: Int!
  defaultCategory: TransactionCategory
}

operations.reducer:
if (action.input.paymentTermsDays < 0) throw new InvalidTermsError("Payment terms cannot be negative");
state.paymentTermsDays = action.input.paymentTermsDays;
if (action.input.defaultCategory !== undefined && action.input.defaultCategory !== null) {
  state.defaultCategory = action.input.defaultCategory;
}

const tag = action.input.tag.trim();
if (tag.length === 0) throw new InvalidTagError("A tag needs text");
if (state.tags.includes(tag)) throw new DuplicateTagError(`Tag ${tag} exists`);
state.tags.push(tag);

const index = state.tags.indexOf(action.input.tag);
if (index === -1) throw new TagNotFoundError(`Tag ${action.input.tag} not found`);
state.tags.splice(index, 1);

state.people.push({
  id: action.input.id,
  name: action.input.name,
  role: action.input.role || null,
  email: action.input.email || null,
  phone: action.input.phone || null,
});

const person = state.people.find((p) => p.id === action.input.id);
if (!person) throw new PersonNotFoundError(`Person ${action.input.id} not found`);
if (action.input.name !== undefined && action.input.name !== null) person.name = action.input.name;
if (action.input.role !== undefined) person.role = action.input.role;
if (action.input.email !== undefined) person.email = action.input.email;
if (action.input.phone !== undefined) person.phone = action.input.phone;

const index = state.people.findIndex((p) => p.id === action.input.id);
if (index === -1) throw new PersonNotFoundError(`Person ${action.input.id} not found`);
state.people.splice(index, 1);

const next = action.input.archived ? "ARCHIVED" : "ACTIVE";
if (state.status === next) throw new StatusUnchangedError(`The contact is already ${next.toLowerCase()}`);
state.status = next;
